const visibleProjects = `-- name: VisibleProjects :many
SELECT id, slug, name, default_branch, namespace, icon, blurb, release_domain, model_profile, owner_group, default_approvers, created_at, require_independent_approval, settings_revision, purpose FROM projects WHERE id=ANY($1::uuid[]) AND purpose = 'ordinary'
AND NOT EXISTS (SELECT 1 FROM project_lifecycle l WHERE l.project_id = projects.id AND l.state = 'deleted')
ORDER BY namespace, name, id
`

// The project lists show ordinary projects: a throwaway eval copy appears
// under its eval, never as a project.
func (q *Queries) VisibleProjects(ctx context.Context, dollar_1 []ids.ID) ([]Project, error) {
	rows, err := q.db.QueryContext(ctx, visibleProjects, pq.Array(dollar_1))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Project
	for rows.Next() {
		var i Project
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Name,
			&i.DefaultBranch,
			&i.Namespace,
			&i.Icon,
			&i.Blurb,
			&i.ReleaseDomain,
			&i.ModelProfile,
			&i.OwnerGroup,
			&i.DefaultApprovers,
			&i.CreatedAt,
			&i.RequireIndependentApproval,
			&i.SettingsRevision,
			&i.Purpose,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
